/**
 * Registry-driven parity: every `Definition` across the four registries emits exactly one well-formed
 * cssdoc record of the right kind/name with no token drift. This replaces the old source-text-scanning
 * "every rule function carries a record tag" test (which broke once the monolith was split).
 */
import { expect, test } from "vite-plus/test";
import { COMPONENTS } from "../src/components/index.ts";
import { DECLARATIONS } from "../src/declarations/index.ts";
import { RULES } from "../src/rules/index.ts";
import { UTILITIES } from "../src/utilities/index.ts";
import { validate } from "./_validate.ts";

const ALL = [...COMPONENTS, ...UTILITIES, ...RULES, ...DECLARATIONS];

test("every registered definition is a single well-formed record (sanity: the registries are populated)", () => {
  // COMPONENTS is the load-bearing concat order (77: 50 components + icon/screen-reader-content +
  // view/mask (moved here from UTILITIES, real components now) + the `menu.item`/`menu.group`/
  // `menu.separator`, `tabs.tab`/`tabs.panel`, `breadcrumb.link`, `calendar.day`, `pagination.page`,
  // `side-nav-bar.item`, `global-nav-bar.item`, `modal.header`/`modal.body`/`modal.footer`, and
  // `drawer-layout.tray`/`drawer-layout.content`,
  // `table.head`/`table.body`/`table.row`/`table.cell`/`table.col-header`/`table.row-header`, and
  // `list.item` members).
  expect(COMPONENTS.length).toBe(78);
  expect(UTILITIES.length).toBe(14);
  expect(RULES.length).toBe(2);
  expect(DECLARATIONS.length).toBe(2);
});

test("every registered definition has a unique name (guards @memberOf cross-file resolution)", () => {
  // `icon`/`screen-reader-content` intentionally appear in both COMPONENTS (their `componentsCss()`
  // concat position) and UTILITIES (the same `Definition` object, for `validate()` coverage) — dedupe
  // by object identity first so that legitimate double-registration isn't mistaken for a name
  // collision between two DIFFERENT records.
  const uniqueDefs = [...new Set(ALL)];
  const names = uniqueDefs.map((def) => def.name);
  expect(new Set(names).size).toBe(names.length);
});

for (const def of ALL) {
  const timeout = def.name === "spacing" ? 20_000 : undefined;
  if (timeout) {
    test(
      `${def.kind} ${def.name}: emits one well-formed cssdoc record, no token drift`,
      () => {
        validate(def);
      },
      timeout,
    );
  } else {
    test(`${def.kind} ${def.name}: emits one well-formed cssdoc record, no token drift`, () => {
      validate(def);
    });
  }
}

/**
 * Shared test helper: assert a {@link Definition} is well-formed — its emitted CSS parses to exactly
 * one `@cssdoc/core` record of the declared kind/name, and every `var(--instui-*)` it references exists
 * in the token IR. Reuses the real cssdoc parser (not a regex) so the per-record guard matches the
 * emitter's own view of the record.
 *
 * @module
 */
import { CssDocConfigFile } from "@cssdoc/config";
import { parseCssDocs } from "@cssdoc/core";
import { byTheme } from "@pantoken/tokens";
import { unknownReferences } from "@pantoken/utils";
import type { Definition } from "../src/lib/define.ts";

// The repo's shared cssdoc.json (root) — loaded once so the per-record guard parses with the same tag
// configuration the docs emitter and lint plugins use. `loadForFolder` walks up from the tests dir.
const configuration = CssDocConfigFile.loadForFolder(import.meta.dirname).toConfiguration();

// Elevation shadows and the focus ring are declared by the sheets themselves (via `@property`), not
// the base token IR.
const isLocal = (ref: string): boolean =>
  ref.startsWith("--instui-elevation-") || ref.startsWith("--instui-focus-outline-");

/** Assert a definition is well-formed; throws (naming the record) on the first problem. */
export function validate(def: Definition): void {
  const css = def.css({ prefix: "instui", theme: "rebrand" });
  const entries = parseCssDocs(css, { configuration });
  if (entries.length !== 1)
    throw new Error(`${def.name}: expected exactly one cssdoc record, got ${entries.length}`);
  const [entry] = entries;
  if (entry.kind !== def.kind)
    throw new Error(`${def.name}: parsed kind "${entry.kind}" ≠ declared "${def.kind}"`);
  if (entry.name !== def.name)
    throw new Error(`${def.name}: parsed name "${entry.name}" ≠ declared "${def.name}"`);
  for (const theme of ["rebrand", "canvas", "canvasHighContrast"] as const) {
    const themedCss = def.css({ prefix: "instui", theme });
    const drift = unknownReferences(themedCss, byTheme(theme)).filter((r) => !isLocal(r));
    if (drift.length)
      throw new Error(`${def.name} (${theme}): unknown token reference(s): ${drift.join(", ")}`);
  }
}

