  for (const theme of themes) {
    const allTokens = perTheme.get(theme) ?? [];
    const tokens = allTokens.filter((t) => varying.has(t.name));
    blocks.push(
      toCss(tokens, {
        scope: themeScopeSelectors(theme),
        layer: "pantoken.theme",
        emit: "declarations",
        declareAll: true,
